class PrivateLotStrategySystem(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.symbols = {
            "SPY": self.AddEquity("SPY", Resolution.Daily).Symbol,
            "AAPL": self.AddEquity("AAPL", Resolution.Daily).Symbol,
            "IBM": self.AddEquity("IBM", Resolution.Daily).Symbol,
            "BAC": self.AddEquity("BAC", Resolution.Daily).Symbol,
            "AIG": self.AddEquity("AIG", Resolution.Daily).Symbol
        }

        self.windows = {
            symbol: RollingWindow[TradeBar](201)
            for symbol in self.symbols.values()
        }

        self.rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self.spy_lot = 0
        self.aapl_lot = 0

    def OnData(self, data):
        bars = {}

        for symbol in self.symbols.values():
            if data.Bars.ContainsKey(symbol):
                bar = data.Bars[symbol]
                bars[symbol] = bar
                self.windows[symbol].Add(bar)

        if self.symbols["AAPL"] in bars:
            self.rsi.Update(bars[self.symbols["AAPL"]].EndTime, bars[self.symbols["AAPL"]].Close)

        if len(bars) != len(self.symbols):
            return

        spy_window = self.windows[self.symbols["SPY"]]
        aapl_window = self.windows[self.symbols["AAPL"]]

        if not spy_window.IsReady or not aapl_window.IsReady or not self.rsi.IsReady:
            return

        spy_close = bars[self.symbols["SPY"]].Close
        aapl_close = bars[self.symbols["AAPL"]].Close

        spy_sma_200_today = sum(spy_window[i].Close for i in range(200)) / 200
        spy_sma_200_yesterday = sum(spy_window[i].Close for i in range(1, 201)) / 200

        spy_sma_50_today = sum(spy_window[i].Close for i in range(50)) / 50
        spy_sma_50_yesterday = sum(spy_window[i].Close for i in range(1, 51)) / 50

        spy_close_yesterday = spy_window[1].Close

        aapl_red_3 = (
            aapl_window[0].Close < aapl_window[1].Close and
            aapl_window[1].Close < aapl_window[2].Close and
            aapl_window[2].Close < aapl_window[3].Close
        )

        spy_crosses_above_200 = (
            spy_close_yesterday <= spy_sma_200_yesterday and
            spy_close > spy_sma_200_today
        )

        spy_crosses_below_50 = (
            spy_close_yesterday >= spy_sma_50_yesterday and
            spy_close < spy_sma_50_today
        )

        if self.spy_lot > 0 and spy_crosses_below_50:
            self.MarketOrder(self.symbols["SPY"], -self.spy_lot)
            self.spy_lot = 0

        if self.aapl_lot > 0 and self.rsi.Current.Value > 60:
            self.MarketOrder(self.symbols["AAPL"], -self.aapl_lot)
            self.aapl_lot = 0

        if self.spy_lot == 0 and spy_crosses_above_200:
            quantity = int((self.Portfolio.TotalPortfolioValue * 0.40) // spy_close)
            if quantity > 0:
                self.MarketOrder(self.symbols["SPY"], quantity)
                self.spy_lot = quantity

        if self.aapl_lot == 0 and aapl_red_3:
            cash = self.Portfolio.CashBook["USD"].Amount
            if cash >= 20000:
                quantity = int(20000 // aapl_close)
                if quantity > 0:
                    self.MarketOrder(self.symbols["AAPL"], quantity)
                    self.aapl_lot = quantity
