class ParallelSlotsAlgorithm(QCAlgorithm):

    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1_000_000)

        self.spy = self.add_equity("SPY", Resolution.DAILY).symbol
        self.aapl = self.add_equity("AAPL", Resolution.DAILY).symbol
        self.ibm = self.add_equity("IBM", Resolution.DAILY).symbol
        self.bac = self.add_equity("BAC", Resolution.DAILY).symbol
        self.aig = self.add_equity("AIG", Resolution.DAILY).symbol
        self.symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        self.spy_closes = RollingWindow[float](201)
        self.aapl_closes = RollingWindow[float](15)

        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

    def on_data(self, data: Slice):
        if any(symbol not in data.bars for symbol in self.symbols):
            return

        spy_close = float(data.bars[self.spy].close)
        aapl_close = float(data.bars[self.aapl].close)

        self.spy_closes.add(spy_close)
        self.aapl_closes.add(aapl_close)

        if not self.spy_closes.is_ready or not self.aapl_closes.is_ready:
            return

        sma_200_today = sum(self.spy_closes[i] for i in range(200)) / 200.0
        sma_200_yesterday = sum(self.spy_closes[i] for i in range(1, 201)) / 200.0

        sma_50_today = sum(self.spy_closes[i] for i in range(50)) / 50.0
        sma_50_yesterday = sum(self.spy_closes[i] for i in range(1, 51)) / 50.0

        rsi_14 = self.calculate_rsi_14()

        # Sells are evaluated before buys.
        if self.strategy_a_shares > 0:
            if self.spy_closes[1] >= sma_50_yesterday and spy_close < sma_50_today:
                self.market_on_close_order(self.spy, -self.strategy_a_shares)
                self.strategy_a_shares = 0

        if self.strategy_b_shares > 0:
            if rsi_14 > 60:
                self.market_on_close_order(self.aapl, -self.strategy_b_shares)
                self.strategy_b_shares = 0

        if self.strategy_a_shares == 0:
            if self.spy_closes[1] <= sma_200_yesterday and spy_close > sma_200_today:
                shares = int((self.portfolio.total_portfolio_value * 0.40) // spy_close)
                if shares > 0:
                    self.market_on_close_order(self.spy, shares)
                    self.strategy_a_shares = shares

        if self.strategy_b_shares == 0:
            red_for_three_days = (
                self.aapl_closes[0] < self.aapl_closes[1]
                and self.aapl_closes[1] < self.aapl_closes[2]
                and self.aapl_closes[2] < self.aapl_closes[3]
            )
            if red_for_three_days and self.portfolio.cash >= 20_000:
                shares = int(20_000 // aapl_close)
                if shares > 0:
                    self.market_on_close_order(self.aapl, shares)
                    self.strategy_b_shares = shares

    def calculate_rsi_14(self) -> float:
        gains = 0.0
        losses = 0.0

        for i in range(14):
            change = self.aapl_closes[i] - self.aapl_closes[i + 1]
            if change > 0:
                gains += change
            elif change < 0:
                losses -= change

        average_gain = gains / 14.0
        average_loss = losses / 14.0

        if average_loss == 0:
            return 100.0

        rs = average_gain / average_loss
        return 100.0 - (100.0 / (1.0 + rs))
